// =============================================================
// Workflow B - Code node: build Telegram summary from parser.py JSON
// Input:  $json.stdout  (one JSON line from parser.py)
// Output: [{ json: { summary, pdf_path, ...metrics } }]
// =============================================================

const raw = ($json.stdout || '').trim();
if (!raw) {
  throw new Error('parser.py produced empty stdout — check stderr for the real error');
}

// parser.py prints one JSON object. If there were stray lines, take the
// last line that starts with "{".
const lines = raw.split('\n').map(l => l.trim()).filter(Boolean);
const jsonLine = [...lines].reverse().find(l => l.startsWith('{'));
if (!jsonLine) {
  throw new Error('no JSON found in parser.py stdout:\n' + raw.slice(0, 500));
}

let data;
try {
  data = JSON.parse(jsonLine);
} catch (e) {
  throw new Error(`stdout is not valid JSON: ${e.message}\nFirst 500 chars:\n${jsonLine.slice(0, 500)}`);
}

const records = Array.isArray(data.data_records) ? data.data_records : [];

// ----- formatters -------------------------------------------------
const fmtNgn = v => {
  if (v == null || !Number.isFinite(Number(v))) return 'n/a';
  return '₦' + Number(v).toLocaleString('en-NG', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
};

const fmtPct = v => {
  if (v == null || !Number.isFinite(Number(v))) return 'n/a';
  const n = Number(v);
  return (n >= 0 ? '+' : '') + n.toFixed(2) + '%';
};

// HTML escape for Telegram parse_mode=HTML
const esc = s => String(s == null ? '' : s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// ----- metrics ----------------------------------------------------
const prices = records
  .map(r => Number(r.price_ngn))
  .filter(v => Number.isFinite(v) && v > 0);

const nationalAvg = prices.length
  ? prices.reduce((a, b) => a + b, 0) / prices.length
  : null;

const mom = records.find(r => r.mom_change_pct != null)?.mom_change_pct ?? null;
const yoy = records.find(r => r.yoy_change_pct != null)?.yoy_change_pct ?? null;

// State rows only — drop "Average" / "National" / "All" / "Total"
const stateRows = records.filter(r => {
  const name = String(r.raw_state_name || '').toLowerCase().trim();
  const price = Number(r.price_ngn);
  return (
    r.raw_state_name &&
    Number.isFinite(price) &&
    price > 0 &&
    !['average', 'national', 'all', 'total'].includes(name)
  );
});

stateRows.sort((a, b) => Number(b.price_ngn) - Number(a.price_ngn));

const top3 = stateRows.slice(0, 3);
const bottom3 = stateRows.slice(-3).reverse();

// ----- header -----------------------------------------------------
const months = [
  '', 'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
];
const monthLabel =
  months[Number(data.publication_month)] || String(data.publication_month || '?');

const reportType = data.report_type || 'N/A';
const pubYear = data.publication_year || '?';

// ----- compose message -------------------------------------------
const out = [];
out.push(`📊 <b>NBS Report — ${esc(monthLabel)} ${esc(pubYear)}</b>`);
out.push(`Type: ${esc(reportType)}`);
out.push('');

if (nationalAvg != null) {
  out.push(`📈 <b>National avg:</b> ${fmtNgn(nationalAvg)}`);
}
out.push(`🔼 <b>MoM:</b> ${fmtPct(mom)}   <b>YoY:</b> ${fmtPct(yoy)}`);
out.push('');

if (top3.length) {
  out.push('<b>Top 3 highest:</b>');
  for (const r of top3) {
    out.push(`  • ${esc(r.raw_state_name)} — ${fmtNgn(r.price_ngn)}`);
  }
  out.push('');
}

if (bottom3.length) {
  out.push('<b>Top 3 lowest:</b>');
  for (const r of bottom3) {
    out.push(`  • ${esc(r.raw_state_name)} — ${fmtNgn(r.price_ngn)}`);
  }
  out.push('');
}

out.push(`${stateRows.length} state rows · ${records.length} total records parsed`);

// ----- output -----------------------------------------------------
return [{
  json: {
    summary: out.join('\n'),
    pdf_path: $json.pdf_path || null,
    publication_month: data.publication_month,
    publication_year: data.publication_year,
    report_type: reportType,
    record_count: records.length,
    state_count: stateRows.length,
    national_avg: nationalAvg,
    mom_pct: mom,
    yoy_pct: yoy,
  },
}];
